const names={junior:['Ananya Mishra','Aditya Sahoo','Snehashish Das','Priyanka Panda','Rohan Mohanty','Ishita Patra','Swayam Rout','Sakshi Behera','Aryan Nayak','Diya Pradhan','Sourav Jena','Riya Sahu'],cs:['Shreya Mohanty','Ayush Das','Debasish Panda','Sneha Rout','Ritwik Mishra','Ankita Sahoo','Harsh Patra','Pooja Nayak','Siddharth Jena','Anushka Behera'],core:['Siddhi Panda','Sambit Sahoo','Pratik Das','Swati Mishra','Aman Rout','Ipsita Patra','Raj Mohanty','Nisha Jena','Arnav Nayak','Tanya Behera']};
const scores=[[88,91,97],[93,87,92],[86,94,88],[89,83,91],[81,90,87],[85,84,86],[77,88,89],[84,79,85],[79,82,83],[75,85,81],[78,76,80],[73,77,79]];
const datasets=Object.fromEntries(Object.entries(names).map(([key,list])=>[key,list.map((name,i)=>({name,id:`${key==='junior'?'26':'24'}${key==='core'?'EC':'CS'}${String(101+i).padStart(3,'0')}`,scores:scores[i].map((v,j)=>v-(key==='core'?2:key==='cs'?1:0)),index:i}))]));let category='junior',period='all';const $=s=>document.querySelector(s);const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');const total=p=>period==='all'?p.scores.reduce((a,b)=>a+b,0):p.scores[Number(period)];
function render(){const key=category==='junior'?'junior':$('#track').value;const data=[...datasets[key]].sort((a,b)=>total(b)-total(a));data.forEach((p,i)=>p.rank=i&&total(p)===total(data[i-1])?data[i-1].rank:i+1);const max=period==='all'?300:100;$('#max').textContent=max;const order=[data[1],data[0],data[2]];$('#podium').innerHTML=order.map((p,i)=>`<article class="pod-card ${i===1?'first':''}">${i===1?'<span class="crown">♛</span>':''}<div class="pod-label">${i===1?'SETTING THE STANDARD':i===0?'CHASING GREATNESS':'MAKING THEIR MARK'}</div><div class="avatar">${initials(p.name)}<span class="rank-medal">${p.rank}</span></div><h3>${p.name}</h3><div class="student-id">${p.id}</div><div class="pod-score">${total(p)}<small>/ ${max} pts</small></div><div class="pod-bottom">${i===1?'✦ Leading the way':`${total(data[0])-total(p)} points from the lead`}</div></article>`).join('');const query=$('#search').value.trim().toLowerCase();const filtered=data.filter(p=>(p.name+' '+p.id).toLowerCase().includes(query));$('#count').textContent=`${filtered.length} of ${data.length} contenders · ${category==='junior'?'Junior category':key==='cs'?'Senior · Computer Science':'Senior · Core'} · Demo data`;$('#rows').innerHTML=filtered.length?filtered.map(p=>`<tr><td class="rank ${p.rank<=3?'top-rank':''}">${String(p.rank).padStart(2,'0')}</td><td><div class="contender"><span class="avatar">${initials(p.name)}</span><div><b>${p.name}</b><small>${p.id}</small></div></div></td>${p.scores.map(s=>`<td class="weekly">${s}</td>`).join('')}<td class="points">${total(p)}</td><td class="progress-col"><div class="bar-label">${Math.round(total(p)/max*100)}% of available points</div><div class="bar"><span style="width:${total(p)/max*100}%"></span></div></td></tr>`).join(''):`<tr><td colspan="7" class="empty">No contenders found. Try another name or student ID.</td></tr>`;const weekly=[...datasets[key]].sort((a,b)=>b.scores[2]-a.scores[2])[0];$('#recognition').innerHTML=`<article class="rec"><span class="rec-icon">✦</span><div><small>WEEK 3 TOP PERFORMER</small><h3>${weekly.name}</h3><p>${weekly.scores[2]} / 100 · Setting the pace this week</p></div></article><article class="rec"><span class="rec-icon">↗</span><div><small>EVERY ROUND COUNTS</small><h3>Room for a comeback</h3><p>Two rounds. 200 more points to pursue.</p></div></article><article class="rec"><span class="rec-icon">◎</span><div><small>PERFECT FIVE</small><h3>Keep the streak alive</h3><p>Five weeks of showing up. One special recognition.</p></div></article>`;}
document.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#track').hidden=category==='junior';render()}));$('#week').addEventListener('change',e=>{period=e.target.value;render()});$('#track').addEventListener('change',render);$('#search').addEventListener('input',render);render();
